<script setup lang="ts">const{preferences,pending,loadPreferences,savePreferences}=useAccount();const form=reactive({theme:"system",language:"fa-IR",defaultCity:"isfahan",alertFrequency:"instant",marketingMessages:false,safetyAlerts:true,searchAlerts:true});useHead({title:"تنظیمات حساب — هفت‌سو",meta:[{name:"robots",content:"noindex,nofollow"}]});onMounted(async()=>{const value=await loadPreferences();if(value)Object.assign(form,{theme:value.theme,language:value.language,defaultCity:value.default_city??"",alertFrequency:value.alert_frequency,marketingMessages:value.marketing_messages,safetyAlerts:value.safety_alerts,searchAlerts:value.search_alerts})});</script>
<template><AccountShell title="تنظیمات و ترجیحات" description="نمایش، شهر پیش‌فرض و اعلان‌ها را تنظیم کنید."><form class="account-form settings-form" @submit.prevent="savePreferences(form)"><label>پوسته<select v-model="form.theme"><option value="system">مطابق دستگاه</option><option value="light">روشن</option><option value="dark">تیره</option></select></label><label>شهر پیش‌فرض<input v-model="form.defaultCity" pattern="[a-z0-9-]{2,80}" dir="ltr"></label><label>تناوب اعلان جست‌وجو<select v-model="form.alertFrequency"><option value="instant">فوری</option><option value="daily">روزانه</option><option value="weekly">هفتگی</option></select></label><label class="toggle-row"><input v-model="form.safetyAlerts" type="checkbox">هشدارهای امنیتی</label><label class="toggle-row"><input v-model="form.searchAlerts" type="checkbox">اعلان جست‌وجوهای ذخیره‌شده</label><label class="toggle-row"><input v-model="form.marketingMessages" type="checkbox">پیام‌های پیشنهادی و بازاریابی</label><button class="button button-primary" type="submit" :disabled="pending">ذخیره تنظیمات</button></form><div class="account-row-list"><NuxtLink to="/my/settings/sessions"><div><strong>دستگاه‌ها و نشست‌های فعال</strong><small>مشاهده و بستن دسترسی دستگاه‌ها</small></div><span>‹</span></NuxtLink><NuxtLink to="/my/settings/privacy"><div><strong>حریم خصوصی و داده‌ها</strong><small>رضایت‌ها، دریافت داده و حذف حساب</small></div><span>‹</span></NuxtLink></div></AccountShell></template>
